const designSets={promotion:{name:'이벤트·혜택',desc:'슬로건과 혜택을 크게 알리는 디자인',ref:'promotion',looks:['슬로건 중심','혜택 강조','좌우 분리'],data:{title:'Send Now\nFly Free',short:'Send Now, Fly Free',desc:'가입하고 송금하면 항공권 지원 혜택을 드려요',amount:'300,000',coupon:'',period:'2026.09.01 – 2026.10.31',note:'데모 이벤트 · 실제 운영 정보가 아닙니다.'}},notice:{name:'서비스 공지',desc:'중단 일정과 후속 안내를 정확하게',ref:'notice',looks:['기본 안내','연장 안내','일정 강조'],data:{title:'시스템 교체로 인한\n교통카드 충전 서비스 일시 중단',short:'교통카드 충전 일시 중단',desc:'더 안정적인 서비스를 위한 시스템 교체 작업이 진행됩니다.',period:'9월 15일 오후 1시 ~ 16일 오전 10시',followup:'완료 시 다시 안내드리겠습니다.',noticeMode:'최초 공지',amount:'',note:'예시 일정 · 실제 운영 정보가 아닙니다.'}},education:{name:'정보·교육',desc:'카드를 나누어 이해하기 쉽게 전달',ref:'education',looks:['두 카드 비교','번호로 알아보기','핵심 먼저'],data:{title:'사기범의 명의 도용 수법편',short:'명의 도용, 이렇게 예방해요',desc:'한패스와 알아보는 스캠 예방법',period:'',amount:'',note:'교육 콘텐츠 데모 · 게시 전 내용 검수 필요',cards:[{title:'고수익 알바의 실체',desc:'불법 자금 세탁용 대포통장 및 명의 도용 범죄',art:'scam'},{title:'통장만 빌려주면 고수익?',desc:'대포통장 명의 대여 및 자금 세탁 위험',art:'phone'}]}}};
easy.contentType='promotion';
function cropArt(type){const map={scam:['education',1106,1098,215,510,245,245],phone:['education',1106,1098,676,510,195,240],transport:['notice',1394,490,419,244,220,150],ticket:['promotion',1206,1082,526,785,170,134]};const a=map[type];if(!a)return '';const [file,w,h,x,y,cw,ch]=a;return `<span class="asset-crop" style="aspect-ratio:${cw}/${ch}"><img alt="${{scam:'사기 예방 일러스트',phone:'휴대폰 일러스트',transport:'교통카드 서비스 일러스트',ticket:'항공권 혜택 일러스트'}[type]}" src="assets/${file}.png" style="width:${w/cw*100}%;max-width:none;left:${-x/cw*100}%;top:${-y/ch*100}%"></span>`}
function setArt(c,look=0,spec=3){const type=c.contentType||'promotion',d=c.data,wide=sizes[spec].w/sizes[spec].h>1.7;return `<div class="set-art set-${type} variant-${look} ${wide?'set-wide':''}" style="--ratio:${sizes[spec].w}/${sizes[spec].h}"><header><b>hanpass</b><small>DEMO DESIGN</small></header>${type==='education'?`<div class="set-copy"><span class="set-kicker">${esc(d.desc)}</span><h2 class="btitle">${esc(d.title)}</h2></div><div class="education-cards">${(d.cards||[]).map((card,i)=>`<div class="education-card">${look===1?`<span class="step-number">${String(i+1).padStart(2,'0')}</span>`:card.image?`<img class="card-photo" src="${card.image}" alt="카드 ${i+1} 이미지">`:cropArt(card.art)}<h3>${esc(card.title)}</h3><p>${esc(card.desc)}</p></div>`).join('')}</div>`:type==='notice'?`<div class="set-copy"><span class="set-kicker">${esc(d.noticeMode||'서비스 안내')}</span><h2 class="btitle">${esc(d.title)}</h2><div class="notice-detail"><b>${d.noticeMode==='연장 공지'?'변경 안내':'중단 일정'}</b><p>${esc(d.period)}</p><p>${esc(d.desc)}</p><strong>${esc(d.followup||'')}</strong></div></div><div class="notice-art">${c.asset?`<img class="card-photo" src="${c.asset}" alt="공지 이미지">`:cropArt('transport')}</div>`:`<div class="set-copy"><span class="set-kicker">HANPASS SPECIAL BENEFIT</span><h2 class="btitle">${esc(d.title)}</h2><p>${esc(d.desc)}</p><span class="promo-date">${esc(d.period)}</span></div><div class="promo-benefit">${c.asset?`<img class="card-photo" src="${c.asset}" alt="혜택 이미지">`:look!==0?cropArt('ticket'):''}<span>항공권 지원 혜택</span><b>${esc(d.amount)}<em>원</em></b></div>`}<footer>${esc(d.note)}</footer></div>`}
const originalEasyArt=easyArt;easyArt=function(c,look=0){return c?.contentType?setArt(c,look,c.sizeIds?.[0]??3):originalEasyArt(c,look)};
const originalSetBanner=banner;banner=function(){return camp().contentType?setArt({...camp(),data:data(),asset:state.asset},camp().look||0,state.size):originalSetBanner()};
choicePage=function(){const type=easy.contentType,ds=designSets[type],c=easy.editing&&camp().contentType===type?camp():{contentType:type,data:ds.data};return `<div class="easy-page"><button class="ghost back" data-easy-nav="home">← 용도 다시 선택</button><div class="easy-heading"><span class="eyelabel">01 용도·내용 선택 <span>— 02 디자인 편집 — 03 확인·검수</span></span><h1>어떤 내용을 만들까요?</h1><p>내용에 맞는 디자인과 입력 항목을 준비해 드려요.</p></div><div class="type-choices">${Object.entries(designSets).map(([id,t])=>`<button data-settype="${id}" class="${id===type?'active':''}"><h3>${t.name}</h3><p>${t.desc}</p></button>`).join('')}</div><div class="placement"><b>${kinds[easy.kind][0]} · 노출 위치</b><div class="row">${kinds[easy.kind][3].map(i=>`<button data-place="${i}" class="${easy.placement===i?'active':''}">${sizes[i].name}<small>${sizes[i].w} × ${sizes[i].h}${sizes[i].example?' · 예시 규격':''}</small></button>`).join('')}</div></div><div class="row between" style="margin-bottom:15px"><h2>${ds.name} 디자인</h2><small>첨부 디자인을 바탕으로 재구성한 편집용 샘플</small></div><div class="choice-grid">${ds.looks.map((n,i)=>`<button class="choice-card ${easy.design===i?'selected':''}" data-look="${i}"><div class="set-choice-preview">${setArt(c,i,easy.placement)}</div><div class="choice-caption"><h3>${n}</h3><span class="radio-mark">${easy.design===i?'✓':''}</span></div></button>`).join('')}</div><div class="choice-footer"><button class="ghost" id="needDesign">디자이너에게 도움 요청</button><button class="primary" id="startEasy">이 디자인으로 편집하기 →</button></div></div>`};
const previousSimple=simplePage;simplePage=function(){if(!camp().contentType)return previousSimple();const t=camp().contentType;let html=previousSimple();const start=html.indexOf('<h2>내 행사 내용으로'),end=html.indexOf('<div class="sectionline"></div><button id="saveEasy"',start);if(start<0||end<0||end<=start)return html;const fields=`<h2>${designSets[t].name} 내용 편집</h2><p>필요한 항목만 입력하면 디자인에 반영돼요.</p>${field('title',t==='promotion'?'메인 슬로건':'제목','textarea')}${field('desc',t==='education'?'시리즈·주제 소개':t==='notice'?'중단 사유·상세 안내':'참여 조건·설명','textarea')}${t==='promotion'?field('amount','혜택 금액 (원)')+field('period','행사 기간'):t==='notice'?`<label class="field">공지 유형<select id="noticeMode"><option ${data().noticeMode==='최초 공지'?'selected':''}>최초 공지</option><option ${data().noticeMode==='연장 공지'?'selected':''}>연장 공지</option></select></label>${field('period','중단 일정·변경 일정')}${field('followup','후속 안내','textarea')}`:`<div class="row between"><h3>내용 카드</h3><span class="badge">${data().cards.length} / 4</span></div>${data().cards.map((card,i)=>`<div class="card-input"><div class="row between"><b>카드 ${i+1}</b><div><button class="small" data-move-card="${i}" ${i===0?'disabled':''} aria-label="카드 ${i+1} 위로">↑</button><button class="small" data-remove-card="${i}" ${data().cards.length<=1?'disabled':''}>삭제</button></div></div><label class="field">카드 제목<input data-card-title="${i}" value="${esc(card.title)}"></label><label class="field">카드 설명<textarea data-card-desc="${i}">${esc(card.desc)}</textarea></label><label class="card-upload">이미지 교체<input type="file" accept="image/*" data-card-photo="${i}"></label></div>`).join('')}<button id="addCard" ${data().cards.length>=4?'disabled':''}>＋ 카드 추가</button>`}<details class="sectionspace"><summary>필수 안내 문구</summary>${field('note','유의사항','textarea')}</details>`;return html.slice(0,start)+fields+html.slice(end)};
const prevCreate=createEasy;createEasy=function(copy){if(copy&&!copy.contentType)return prevCreate(copy);const type=copy?.contentType||easy.contentType;const c={name:copy?copy.name+' (복사)':designSets[type].name+' 디자인',owner:'김민지',date:'2026-09-30',status:'작업 중',langs:1,sizes:1,languageIds:[0],sizeIds:[easy.placement],look:easy.design,contentType:type,data:structuredClone(copy?.data||designSets[type].data)};campaigns.push(c);selectWork(c)};
const oldSelectWork=selectWork;selectWork=function(c){easy.contentType=c.contentType||'promotion';oldSelectWork(c)};
function touchSet(){state.version++;state.approved={};state.requested=false;camp().status='수정 필요';state.history.unshift('디자인 내용 변경 · 재검수 필요');state.save='모든 변경사항 저장됨';if($('#canvas'))$('#canvas').innerHTML=banner()}
const priorBind=bindEasy;bindEasy=function(){priorBind();$$('[data-settype]').forEach(b=>b.onclick=()=>{easy.contentType=b.dataset.settype;easy.design=0;render()});if($('#startEasy'))$('#startEasy').onclick=()=>{if(easy.editing){if(camp().contentType!==easy.contentType){confirmBox('내용 유형을 바꿀까요?','기존 작업을 보존하고 선택한 유형의 새 작업을 만듭니다.',()=>{easy.editing=false;createEasy()},'새 작업 만들기');return}camp().look=easy.design;if(!activeSizes().includes(easy.placement)){camp().sizeIds=[...activeSizes(),easy.placement];camp().sizes=camp().sizeIds.length}state.size=easy.placement;touchSet();navigate('simple')}else createEasy()};if($('#changeLook'))$('#changeLook').onclick=()=>{easy.contentType=camp().contentType||'promotion';easy.design=camp().look||0;easy.placement=state.size;easy.editing=true;navigate('choose')};if(!camp().contentType||state.page!=='simple')return;if($('#noticeMode'))$('#noticeMode').onchange=e=>{camp().data.noticeMode=e.target.value;touchSet();render()};$$('[data-card-title]').forEach(e=>e.oninput=()=>{camp().data.cards[+e.dataset.cardTitle].title=e.value;touchSet()});$$('[data-card-desc]').forEach(e=>e.oninput=()=>{camp().data.cards[+e.dataset.cardDesc].desc=e.value;touchSet()});$$('[data-move-card]').forEach(b=>b.onclick=()=>{const i=+b.dataset.moveCard;[camp().data.cards[i-1],camp().data.cards[i]]=[camp().data.cards[i],camp().data.cards[i-1]];touchSet();render()});$$('[data-remove-card]').forEach(b=>b.onclick=()=>confirmBox('이 카드를 삭제할까요?','선택한 카드의 제목·설명·이미지가 삭제됩니다.',()=>{camp().data.cards.splice(+b.dataset.removeCard,1);touchSet();render()},'삭제'));if($('#addCard'))$('#addCard').onclick=()=>{if(camp().data.cards.length<4)camp().data.cards.push({title:'새 카드 제목',desc:'전달할 내용을 입력해 주세요.',art:'phone'});touchSet();render()};$$('[data-card-photo]').forEach(e=>e.onchange=()=>{const f=e.files[0];if(f?.type.startsWith('image/')){camp().data.cards[+e.dataset.cardPhoto].image=URL.createObjectURL(f);touchSet();render()}});if(camp().contentType==='education'){if($('#easyPhoto'))$('#easyPhoto').hidden=true;const help=$('.creator-canvas-help')||$('.simple-canvas>p');if(help)help.textContent='카드별 이미지와 문구는 오른쪽에서 바꿀 수 있어요.'}};
const setStatusBefore=status;status=function(l,s){if(!camp().contentType)return setStatusBefore(l,s);const d=camp().data;if(d.title.length>(sizes[s].w/sizes[s].h>1.7?65:90)||(d.cards||[]).some(c=>c.title.length>35||c.desc.length>100))return '글자 넘침';if(state.approved[l+'-'+s]===state.version)return '승인 완료';if(!state.reviewed[l])return '번역 미검수';return state.requested?'검수 대기':'제작 완료'};
const oldSetRender=render;render=function(){oldSetRender();if(camp().contentType&&$('#easyIssue'))$('#easyIssue').textContent=status(state.lang,state.size)==='글자 넘침'?'! 글자 넘침 · 문구를 줄여 주세요. 자동으로 삭제하지 않아요.':'✓ '+designSets[camp().contentType].name+' 레이아웃 적용 · 데모 검사';if(easy.admin&&state.page==='templates'){const root=$('.contentwrap');root.insertAdjacentHTML('afterbegin',`<div class="card set-admin"><h2>콘텐츠별 디자인 세트</h2><p>입력 항목과 보호 영역을 세트 단위로 관리해요.</p><div class="type-choices">${Object.entries(designSets).map(([id,t])=>`<button data-admin-set="${id}"><h3>${t.name}</h3><p>${t.looks.length}개 구도 · v1.0</p><small>편집 가능: ${id==='education'?'제목·카드·이미지':id==='notice'?'일정·사유·후속 안내':'슬로건·금액·기간'}</small></button>`).join('')}</div><small>🔒 로고·기본 스타일 보호 · 기존 승인 결과물은 새 버전과 분리됩니다.</small></div>`);$$('[data-admin-set]').forEach(b=>b.onclick=()=>{easy.admin=false;easy.contentType=b.dataset.adminSet;easy.editing=false;easy.kind=3;easy.placement=3;easy.design=0;navigate('choose')})}};
for(const [id,t]of Object.entries(designSets))campaigns.push({name:{promotion:'항공권 지원 이벤트 · 샘플',notice:'교통카드 충전 중단 안내 · 샘플',education:'스캠 예방 콘텐츠 · 샘플'}[id],owner:'김민지',date:'2026-09-30',status:'작업 중',langs:1,sizes:1,languageIds:[0],sizeIds:[id==='education'?3:1],look:0,contentType:id,data:structuredClone(t.data)});
render();
